pattern_rows = ["0010","1111","0110","0010"]
cells = [(i,j) for i,r in enumerate(pattern_rows) for j,ch in enumerate(r) if ch=='1']
row_colors = [2,3,4,6,7]
starts = [0,5,10,15,20]
out = [[0]*24 for _ in range(24)]
for s in (4,9,14,19):
    for k in range(24):
        out[s][k]=5; out[k][s]=5
for r in range(5):
    for b in range(5):
        for i,j in cells:
            out[starts[r]+i][starts[b]+j] = row_colors[r]
for row in out: print(''.join(map(str,row)))
